src={(0,0),(0,2),(1,0),(1,3),(2,1),(2,2),(3,2),(3,3)}
obs={(0,4),(0,6),(1,3),(1,6),(2,4),(2,5),(2,6),(3,3),(3,5),(3,6),(4,4),(4,5),(5,5),(5,6)}
def norm(p):
 mr=min(x for x,y in p);mc=min(y for x,y in p);return {(x-mr,y-mc) for x,y in p}
for refl in range(2):
 p=src if refl==0 else {(x,-y) for x,y in src}
 for k in range(4):
  q=norm(p); placements=[]
  for r in range(-3,7):
   for c in range(-4,7):
    z={(r+x,c+y) for x,y in q}
    if z<=obs:placements.append((r,c,z))
  # greedy/exhaustive set cover
  def go(rem, chosen, start=0):
   if not rem:return chosen
   x=next(iter(rem))
   for i,(r,c,z) in enumerate(placements):
    if x in z:
     ans=go(rem-z, chosen+[(r,c,z)])
     if ans:return ans
   return None
  ans=go(set(obs),[])
  if ans:print('cover',refl,k,[(r,c) for r,c,z in ans])
  p={(y,-x) for x,y in p}

